function dsShift_(dateStr, days) { var p = dsDateParts_(dateStr); var d = new Date(Date.UTC(p.y, p.m - 1, p.d + days, 12)); return d.getUTCFullYear() + '-' + ('0' + (d.getUTCMonth() + 1)).slice(-2) + '-' + ('0' + d.getUTCDate()).slice(-2); }

