      if (missBy[i.c + '|' + i.email] >= cfg.repeatMissing || c.health === 'RED') { lvl = 3; why = missBy[i.c + '|' + i.email] >= cfg.repeatMissing ? 'Repeated missing work (' + missBy[i.c + '|' + i.email] + ') — VP / HM' : 'Class needs action — VP / HM'; }
