    ensureSheetHeader_(sheet, EXAMINATION_AUDIT_HEADER);
    sheet.getRange(1, 1, 1, EXAMINATION_AUDIT_HEADER.length).setValues([EXAMINATION_AUDIT_HEADER]).setFontWeight('bold');
